// src/components/HeroSelect.jsx

import React from 'react'
import '../../styles/HeroSelect.css'

export default function HeroesSelect({ onClose }) {
  // List of heroes to display in the grid
  const heroes = [
    { name: 'BLACK PANTHER', image: '/assets/heroCards/blackPanther-Card.png' },
    { name: 'BLADE', image: '/assets/heroCards/bladeCard.png' },
    { name: 'ROCKET RACCOON', image: '/assets/heroCards/rocketCard.png' },
    { name: 'THOR', image: '/assets/heroCards/thorCard.png' },
    { name: 'ULTRON', image: '/assets/heroCards/ultronCard.png' },
    { name: 'VENOM', image: '/assets/heroCards/venomCard.png' },
  ]

  return (
    // Dark blurred full-screen overlay behind the hero select panel
    <div className="heroes-select-overlay">
      {/* Main hero selection panel */}
      <div className="heroes-select">
        {/* Giant transparent background text ("HERO SELECT") */}
        <div className="bg-text">
          HERO
          <br />
          SELECT
        </div>

        {/* Close button (top-right) */}
        <button className="close-btn" onClick={onClose}>
          ✕
        </button>

        {/* Sticky header image that stays visible while scrolling */}
        <div className="header-wrapper">
          <img
            src="/assets/hero-select-header.png"
            alt="Heroes Select"
            className="header-image"
          />
        </div>

        {/* Scrollable area containing all hero cards */}
        <div className="heroes-scroll-area">
          {/* Grid of hero cards */}
          <div className="heroes-grid">
            {heroes.map((hero, index) => (
              <div className="hero-card" key={index}>
                <img src={hero.image} alt={hero.name} className="hero-img" />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}
